#!/usr/bin/env python3
"""v43 : fenêtre « création concurrente » (œil sur une pub de la Meta Ads Library), au design de l'application.
Remplace uniquement la fonction AdLightbox de src/components/chat/CompetitorAdsCard.tsx (mêmes props, mêmes actions :
flèches, clavier, Ajouter en référence, Voir dans la bibliothèque) et crée src/styles/gx-ad-lightbox.css.
Usage : python3 apply-v43.py [--check]"""
import sys, pathlib, json
CHECK = "--check" in sys.argv
F = pathlib.Path("src/components/chat/CompetitorAdsCard.tsx")
CSS_PATH = pathlib.Path("src/styles/gx-ad-lightbox.css")
NEW_FN = json.loads(r'''"function AdLightbox({\n  ads,\n  index,\n  onClose,\n  onNavigate,\n  selected,\n  onToggle,\n}: {\n  ads: Ad[];\n  index: number;\n  onClose: () => void;\n  onNavigate: (next: number) => void;\n  selected?: boolean;\n  onToggle?: () => void;\n}) {\n  const ad = ads[index];\n  const platforms = (ad.platforms ?? []).map((platform) => platformLabels[platform.toLowerCase()] ?? platform);\n  const [mediaFailed, setMediaFailed] = useState(false);\n  const mediaUrl = mediaFailed ? undefined : (ad.mediaUrl ?? undefined);\n  useEffect(() => setMediaFailed(false), [ad.mediaUrl]);\n\n  useEffect(() => {\n    const onKey = (event: KeyboardEvent) => {\n      if (event.key === \"ArrowLeft\") onNavigate(index - 1);\n      if (event.key === \"ArrowRight\") onNavigate(index + 1);\n    };\n    window.addEventListener(\"keydown\", onKey);\n    return () => window.removeEventListener(\"keydown\", onKey);\n  }, [index, onNavigate]);\n\n  const signalCls = ad.signal === \"fort\" ? \"cl-sig cl-sig-ok\" : ad.signal === \"prometteur\" ? \"cl-sig cl-sig-ac\" : \"cl-sig\";\n\n  // Fenêtre au design de l'application : en-tête, création à gauche (flèches dessus), analyse à droite.\n  return (\n    <DialogPrimitive.Root open onOpenChange={(open) => { if (!open) onClose(); }}>\n      <DialogPrimitive.Portal>\n        <DialogPrimitive.Overlay className=\"cl-overlay\" />\n        <DialogPrimitive.Content className=\"cl-dlg console-app-portal\" aria-describedby={undefined}>\n          <header className=\"cl-h\">\n            <DialogPrimitive.Title asChild>\n              <div className=\"cl-who\"><PageIdentity ad={ad} large /></div>\n            </DialogPrimitive.Title>\n            <span className={signalCls}><i aria-hidden />{(ad.signal ?? \"à surveiller\").replace(/^./, (c) => c.toUpperCase())}</span>\n            <span className=\"cl-sp\" />\n            <span className=\"cl-count\">{index + 1} / {ads.length}</span>\n            <DialogPrimitive.Close className=\"cl-ib\" aria-label=\"Fermer\"><X className=\"gx-i\" /></DialogPrimitive.Close>\n          </header>\n          <div className=\"cl-body\">\n            <div className=\"cl-media\">\n              {mediaUrl && ad.mediaType === \"video\" ? (\n                <video key={mediaUrl} src={mediaUrl} controls autoPlay playsInline onError={() => setMediaFailed(true)} />\n              ) : mediaUrl ? (\n                <img key={mediaUrl} src={mediaUrl} alt={`Publicité de ${ad.pageName ?? \"cet annonceur\"}`} onError={() => setMediaFailed(true)} />\n              ) : (\n                <div className=\"cl-na\">\n                  <b>Aperçu indisponible</b>\n                  <p>La création n’a pas pu être récupérée depuis la bibliothèque officielle.</p>\n                  {ad.libraryUrl ? (\n                    <a className=\"cl-btn\" href={ad.libraryUrl} target=\"_blank\" rel=\"noopener noreferrer\"><ExternalLink className=\"gx-i\" /> Voir la création réelle</a>\n                  ) : null}\n                </div>\n              )}\n              {index > 0 ? (\n                <button type=\"button\" aria-label=\"Création précédente\" className=\"cl-arr cl-prev\" onClick={() => onNavigate(index - 1)}><ChevronLeft className=\"gx-i\" /></button>\n              ) : null}\n              {index < ads.length - 1 ? (\n                <button type=\"button\" aria-label=\"Création suivante\" className=\"cl-arr cl-next\" onClick={() => onNavigate(index + 1)}><ChevronRight className=\"gx-i\" /></button>\n              ) : null}\n            </div>\n            <aside className=\"cl-side\">\n              <div className=\"cl-scroll\">\n                <div className=\"cl-facts\">\n                  <div><span><Clock className=\"gx-i\" aria-hidden />Diffusion</span><b>{`${ad.runningDays ?? 0} jours${ad.stillActive ? \" · active\" : \"\"}`}</b></div>\n                  <div><span><CalendarDays className=\"gx-i\" aria-hidden />Période</span><b>{`${formatDate(ad.startedAt)} → ${formatDate(ad.endedAt)}`}</b></div>\n                  <div><span><Users2 className=\"gx-i\" aria-hidden />Portée UE</span><b>{typeof ad.euReach === \"number\" ? ad.euReach.toLocaleString(\"fr-FR\") : \"Non publiée\"}</b></div>\n                  <div><span><Layers3 className=\"gx-i\" aria-hidden />Plateformes</span><b>{platforms.length ? platforms.join(\", \") : \"Non précisées\"}</b></div>\n                </div>\n                {ad.body ? <div className=\"cl-det\"><h4>Texte de l’accroche</h4><p>{ad.body}</p></div> : null}\n                {ad.title ? <div className=\"cl-det\"><h4>Titre</h4><p>{ad.title}</p></div> : null}\n                {ad.description ? <div className=\"cl-det\"><h4>Description</h4><p>{ad.description}</p></div> : null}\n                {ad.destination ? <div className=\"cl-det\"><h4>Destination affichée</h4><p>{ad.destination}</p></div> : null}\n                {(ad.signalReasons ?? []).length ? (\n                  <div className=\"cl-det\">\n                    <h4>Pourquoi ce signal</h4>\n                    <ul>\n                      {(ad.signalReasons ?? []).map((reason) => (\n                        <li key={reason}><TrendingUp className=\"gx-i\" aria-hidden />{reason}</li>\n                      ))}\n                    </ul>\n                  </div>\n                ) : null}\n              </div>\n              {onToggle || ad.libraryUrl ? (\n                <div className=\"cl-act\">\n                  {onToggle ? (\n                    <button type=\"button\" className={`cl-btn${selected ? \" cl-on\" : \" cl-pri\"}`} aria-pressed={selected} onClick={onToggle}>\n                      {selected ? <Check className=\"gx-i\" /> : <Plus className=\"gx-i\" />}\n                      {selected ? \"Référence ajoutée\" : \"Ajouter en référence\"}\n                    </button>\n                  ) : null}\n                  {ad.libraryUrl ? (\n                    <a className=\"cl-btn\" href={ad.libraryUrl} target=\"_blank\" rel=\"noopener noreferrer\"><ExternalLink className=\"gx-i\" /> Voir dans la bibliothèque officielle</a>\n                  ) : null}\n                </div>\n              ) : null}\n            </aside>\n          </div>\n        </DialogPrimitive.Content>\n      </DialogPrimitive.Portal>\n    </DialogPrimitive.Root>\n  );\n}\n\n"''')
CSS = json.loads(r'''"/* Fenêtre « création concurrente » (Meta Ads Library), au design de l'application : jetons --app-*, clair et sombre. */\n.cl-overlay{position:fixed;inset:0;z-index:79;background:var(--app-overlay,rgba(0,0,0,.5))}\n.cl-dlg{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:80;width:min(1040px,calc(100vw - 24px));height:min(760px,calc(100dvh - 24px));display:flex;flex-direction:column;overflow:hidden;background:var(--app-surface);color:var(--app-fg);border:1px solid var(--app-line);border-radius:20px;box-shadow:var(--app-sh-lg);font:14px/1.5 var(--font-sans,\"Inter\",ui-sans-serif,system-ui,sans-serif)}\n.cl-dlg *,.cl-dlg *::before,.cl-dlg *::after{box-sizing:border-box}\n.cl-dlg .gx-i{width:16px;height:16px;flex:none}\n\n.cl-h{display:flex;align-items:center;gap:10px;padding:14px 16px 14px 20px;border-bottom:1px solid var(--app-line);flex:none;min-width:0}\n.cl-who{min-width:0;flex:0 1 auto;margin:0;font:inherit}\n.cl-dlg .gx-cads-pid{display:flex;align-items:center;gap:10px;min-width:0}\n.cl-dlg .gx-cads-av{width:40px;height:40px;border-radius:50%;object-fit:cover;border:1px solid var(--app-line);background:var(--app-sunk);display:grid;place-items:center;font-weight:700;color:var(--app-muted);flex:none}\n.cl-dlg .gx-cads-pn{min-width:0;display:flex;flex-direction:column;line-height:1.25}\n.cl-dlg .gx-cads-pn a,.cl-dlg .gx-cads-pn b{font-weight:600;font-size:15px;color:var(--app-fg);text-decoration:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.cl-dlg .gx-cads-pn a:hover{text-decoration:underline;text-underline-offset:3px}\n.cl-dlg .gx-cads-pn small{color:var(--app-dim);font-size:12.5px}\n.cl-sig{display:inline-flex;align-items:center;gap:6px;height:24px;padding:0 9px;border-radius:999px;background:var(--app-sunk);color:var(--app-dim);font-size:12px;font-weight:600;white-space:nowrap;flex:none}\n.cl-sig i{width:6px;height:6px;border-radius:50%;background:currentColor}\n.cl-sig-ok{background:var(--app-ok-soft);color:var(--app-ok)}\n.cl-sig-ac{background:var(--app-accent-soft);color:var(--app-accent-ink)}\n.cl-sp{flex:1}\n.cl-count{font-size:13px;color:var(--app-dim);font-variant-numeric:tabular-nums;white-space:nowrap}\n.cl-ib{width:34px;height:34px;border:0;border-radius:9px;background:none;color:var(--app-dim);display:grid;place-items:center;cursor:pointer;flex:none;padding:0}\n.cl-ib:hover{background:var(--app-sunk);color:var(--app-fg)}\n\n.cl-body{flex:1;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 360px}\n.cl-media{position:relative;min-width:0;min-height:0;overflow:hidden;background:#0B0B0F}\n.cl-media>video,.cl-media>img{position:absolute;inset:16px 56px;width:calc(100% - 112px);height:calc(100% - 32px);object-fit:contain;display:block}\n.cl-media>.cl-na{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(320px,calc(100% - 112px))}\n.cl-na{max-width:320px;padding:20px;border-radius:14px;background:var(--app-surface);display:flex;flex-direction:column;gap:8px;text-align:center;align-items:center}\n.cl-na b{font-weight:600}\n.cl-na p{margin:0;color:var(--app-dim);font-size:13px}\n.cl-arr{position:absolute;top:50%;transform:translateY(-50%);width:38px;height:38px;border-radius:50%;border:0;background:rgba(255,255,255,.92);color:#111;display:grid;place-items:center;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,.3);z-index:2}\n.cl-arr:hover{background:#fff}\n.cl-prev{left:10px}.cl-next{right:10px}\n\n.cl-side{min-width:0;min-height:0;display:flex;flex-direction:column;border-left:1px solid var(--app-line)}\n.cl-scroll{flex:1;min-height:0;overflow-y:auto;padding:16px 18px;display:flex;flex-direction:column;gap:16px}\n.cl-facts{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.cl-facts>div{min-width:0;padding:10px 12px;border:1px solid var(--app-line);border-radius:12px;background:var(--app-raised);display:flex;flex-direction:column;gap:3px}\n.cl-facts span{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--app-dim)}\n.cl-facts span .gx-i{width:13px;height:13px}\n.cl-facts b{font-size:13.5px;font-weight:600;line-height:1.35;overflow-wrap:break-word;word-break:normal;hyphens:none;font-variant-numeric:tabular-nums}\n.cl-det h4{margin:0 0 4px;font-size:11.5px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--app-dim)}\n.cl-det p{margin:0;font-size:14px;line-height:1.55;color:var(--app-muted);white-space:pre-line;overflow-wrap:anywhere}\n.cl-det ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px}\n.cl-det li{display:flex;align-items:flex-start;gap:8px;font-size:13.5px;color:var(--app-muted)}\n.cl-det li .gx-i{width:14px;height:14px;margin-top:3px;color:var(--app-ok)}\n.cl-act{flex:none;display:flex;flex-direction:column;gap:8px;padding:12px 18px;border-top:1px solid var(--app-line);background:var(--app-raised)}\n.cl-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:38px;padding:0 14px;border:1px solid var(--app-line2);border-radius:10px;background:var(--app-surface);color:var(--app-fg);font:500 14px var(--font-sans,\"Inter\",system-ui,sans-serif);text-decoration:none;cursor:pointer;width:100%}\n.cl-btn:hover{background:var(--app-raised)}\n.cl-btn.cl-pri{background:var(--app-accent);border-color:var(--app-accent);color:var(--app-on-accent);font-weight:600}\n.cl-btn.cl-pri:hover{background:var(--app-accent-hover)}\n.cl-btn.cl-on{background:var(--app-accent-soft);border-color:var(--app-accent);color:var(--app-accent-ink);font-weight:600}\n.cl-na .cl-btn{width:auto}\n\n@media (max-width:820px){\n  .cl-dlg{height:calc(100dvh - 24px)}\n  .cl-body{grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(220px,48%) minmax(0,1fr)}\n  .cl-media>video,.cl-media>img{inset:12px 52px;width:calc(100% - 104px);height:calc(100% - 24px)}\n  .cl-side{border-left:0;border-top:1px solid var(--app-line)}\n  .cl-h{padding:12px}\n  .cl-count{display:none}\n}\n"''')
IMPORT_OLD = 'import { Dialog, DialogClose, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";\n'
IMPORT_NEW = 'import * as DialogPrimitive from "@radix-ui/react-dialog";\nimport "@/styles/gx-ad-lightbox.css";\n'
START, END = "function AdLightbox({", "function Detail({ label, value }"
s = F.read_text(); ok = True
for m in (START, END, IMPORT_OLD):
    if s.count(m) != 1: print(f"ÉCHEC : trouvé {s.count(m)} fois : {m[:70]!r}"); ok = False
if ok:
    a, b = s.index(START), s.index(END)
    old_fn = s[a:b]
    if "gx-ad-lightbox-layout" not in old_fn or b < a: print("ÉCHEC : AdLightbox n'est pas la version attendue"); ok = False
if CSS_PATH.exists(): print("ÉCHEC : src/styles/gx-ad-lightbox.css existe déjà"); ok = False
if ok:
    s = s.replace(IMPORT_OLD, IMPORT_NEW)
    a, b = s.index(START), s.index(END)
    s = s[:a] + NEW_FN + s[b:]
    for name in ("DialogContent", "DialogHeader", "DialogTitle", "DialogClose", "<Dialog "):
        if name in s.replace("DialogPrimitive.", ""): print("ÉCHEC : reste", name); ok = False
if ok and not CHECK:
    F.write_text(s); CSS_PATH.write_text(CSS)
print("OK" if ok else "ÉCHEC", "(vérification seule)" if CHECK else "")
sys.exit(0 if ok else 1)
